"""Chapter 8: Results and output screens. Every number is read from models/training_report.json and docs/experiments/*.json."""

from . import facts as F
from .blocks import B, FIG, FIGPAIR, H1, H2, P, TAB

X, R, A = F.X, F.REAL, F.API
D = F.DISEASES
NAME = F.NAME
FIG_W = 4.0      # width (in) of result charts; lower it to shorten the chapter
SCREEN_W = 3.9   # width (in) of output screens


def cite(*keys):
    """[n] citation string from refs.NUM (falls back to [?] while refs.py is not yet written)."""
    try:
        from .refs import NUM

        return "[" + ", ".join(str(NUM[k]) for k in keys) + "]"
    except Exception:
        return "[?]"


def shot(name):
    return F.shot(name)


def ms(m, key):
    return f"{m[key + '_mean']:.4f} ± {m[key + '_std']:.4f}"


def sweep(d, t):
    return next(s for s in X[d]["threshold_sweep"] if abs(s["threshold"] - t) < 1e-9)


def best_sweep(d):
    return max(X[d]["threshold_sweep"], key=lambda s: s["f1"])


def cm(d):
    (tn, fp), (fn, tp) = X[d]["confusion"][F.BEST[d]]
    return tn, fp, fn, tp


def blocks():
    HDR = ["Model", "Accuracy", "Precision", "Recall", "F1-score", "ROC-AUC"]
    AL = ["l", "c", "c", "c", "c", "c"]
    out = [
        H1("CHAPTER 8: RESULTS AND OUTPUT SCREENS"),
        H2("8.1 Experimental Setup"),
        P("All results come from the project's own scripts: `train_models.py` (the metrics the application shows, stored in `models/training_report.json`), `scripts/run_experiments.py` (ROC-AUC, confusion matrices, cross-validation, "
          "repeated splits, thresholds, importance, sensitivity), `scripts/real_data_check.py` (a supplementary check on real public data), `scripts/api_tests.py` (API checks and latency) and `scripts/make_figures.py` (charts). "
          "Re-running them reproduces the numbers below on the same software versions; `run_experiments.py` reproduces all 16 model-and-disease cells of the shipped report to four decimals."),
        TAB("Experimental setup", ["Item", "Value"],
            [["Data", "Four **synthetic** CSV files in `data/`, 2,000 rows each (8,000 in total), generated by `generate_data.py` (seed 42): a hand-written linear risk score, thresholded at 0.5, with 8% of the labels flipped at random"],
             ["Split", "Stratified 80/20, random_state 42: 1,600 training rows and 400 test rows for every disease"],
             ["Models", "Logistic Regression (max_iter 1000), Decision Tree (max_depth 6), Random Forest (200 trees, max_depth 8), SVM (RBF, C 1, probability on); inputs standardised with a scaler fitted on the training rows"],
             ["Selection rule", "Highest F1 on the test split (as in `train_models.py`)"],
             ["Extra protocols", "Stratified 5-fold cross-validation (scaler refitted per fold) and ten random 80/20 splits (seeds 0-9) for all four algorithms"],
             ["Real-data check", "Pima Indians Diabetes, UCI Cleveland heart, UCI ILPD liver and UCI chronic kidney disease, same algorithms and settings with median imputation (Section 8.8)"],
             ["Machine", "Intel Core i5-12500 (12 threads), 16 GB RAM, Windows 11, Python 3.11.9, scikit-learn 1.8.0, CPU only"]],
            widths=[1.3, 4.7], size=9.5),
        P("**Reading the numbers.** The training data are synthetic. Their labels follow a known linear rule and 8% of them are flipped, so no classifier can exceed about 92% accuracy on this data (the noise ceiling) and a linear model is the correct model family. "
          "The accuracies below therefore show that the pipeline recovers a known rule; they are **not clinical performance**. Section 8.8 shows what the same method scores on real public data."),
        H2("8.2 Hold-out Results for the Four Diseases"),
        P("The tables give the four algorithms for each disease on the 400-row test split. The row marked (selected) is the model the application serves; accuracy, precision, recall and F1 are the values stored in the training report and shown on the Models page, "
          "and ROC-AUC was computed afterwards from the predicted probabilities of the same fitted models."),
    ]
    for d in D:
        best = F.BEST[d]
        rows = []
        for m in F.MODEL_ORDER:
            r, h = F.HO[d][m], X[d]["holdout"][m]
            rows.append([m + (" (selected)" if m == best else ""), f"{r['accuracy']:.4f}", f"{r['precision']:.4f}", f"{r['recall']:.4f}", f"{r['f1']:.4f}", f"{h['roc_auc']:.4f}"])
        out.append(TAB(f"{NAME[d]}: test-split metrics ({X[d]['test_rows']} rows, {X[d]['test_positive']} high-risk)", HDR, rows, widths=[1.9, 0.8, 0.8, 0.7, 0.8, 0.8], align=AL, size=9.5))
    b = F.BEST
    pb = {d: F.pct(X[d]['positive'] / X[d]['rows']) for d in D}
    out += [
        FIG(F.fig("model_comparison.png"), "Hold-out metrics of the four algorithms for each disease (outlined bars: the model served by the application; dashed line: 92% noise ceiling)", FIG_W),
        P(f"Three points stand out. **First**, the selected models score {F.pct(F.HO['diabetes'][b['diabetes']]['accuracy'])} (diabetes), {F.pct(F.HO['heart'][b['heart']]['accuracy'])} (heart), "
          f"{F.pct(F.HO['liver'][b['liver']]['accuracy'])} (liver) and {F.pct(F.HO['kidney'][b['kidney']]['accuracy'])} (kidney), all close to the 92% ceiling set by the label noise. "
          "**Second**, Logistic Regression is the selected model for three of the four diseases and is within 0.5 points of the SVM for the fourth, which is what a linear label rule predicts. "
          "**Third**, the Decision Tree is clearly the weakest everywhere (accuracy 0.7450 to 0.8600) and Random Forest is behind the linear model on every disease, because both fit the flipped labels (Section 8.5)."),
        P(f"Recall matters most when a screening tool must not miss patients. Heart disease has the highest recall of the selected models (0.9589) because its data are 73.1% high-risk; liver disease has the lowest (0.7768) with 28.1% high-risk rows, "
          "so the liver model misses about one high-risk patient in four. Precision and recall are not averaged across diseases because the class balance differs (high-risk share of the 2,000 rows: diabetes {pb['diabetes']}, heart {pb['heart']}, liver {pb['liver']}, kidney {pb['kidney']})."),
        H2("8.3 Confusion Matrices and ROC Curves"),
    ]
    rows = []
    for d in D:
        tn, fp, fn, tp = cm(d)
        rows.append([NAME[d], F.BEST[d], str(tn), str(fp), str(fn), str(tp), f"{fn / (fn + tp) * 100:.1f}%", f"{fp / (fp + tn) * 100:.1f}%"])
    out += [
        TAB("Confusion matrices of the served models on the 400-row test split", ["Disease", "Model", "TN", "FP", "FN", "TP", "High-risk missed", "Low-risk flagged"],
            rows, widths=[1.1, 1.5, 0.45, 0.45, 0.45, 0.45, 0.85, 0.85], align=["l", "l", "c", "c", "c", "c", "c", "c"], size=9),
        FIG(F.fig("confusion_matrices.png"), "Confusion matrices of the served model for each disease (rows: actual label; columns: prediction)", FIG_W),
        P(f"The error types differ by disease. The diabetes model has few false alarms ({cm('diabetes')[1]} of {cm('diabetes')[0] + cm('diabetes')[1]} low-risk rows) but misses {cm('diabetes')[2]} of {cm('diabetes')[2] + cm('diabetes')[3]} high-risk rows; "
          f"the heart model does the opposite, flagging {cm('heart')[1]} of {cm('heart')[0] + cm('heart')[1]} low-risk rows and missing only {cm('heart')[2]} of {cm('heart')[2] + cm('heart')[3]}; "
          f"the liver model misses {cm('liver')[2]} of {cm('liver')[2] + cm('liver')[3]} high-risk rows; and the kidney model makes both kinds of error ({cm('kidney')[1]} false alarms, {cm('kidney')[2]} misses). "
          "The heart behaviour follows from the class balance: with 73% positives, calling most records high-risk is rarely wrong."),
        FIG(F.fig("roc_curves.png"), "ROC curves of the four algorithms for each disease on the test split", FIG_W - 0.4),
        P("ROC-AUC separates the algorithms less than accuracy does: for diabetes Logistic Regression, Random Forest and SVM have AUC 0.9034, 0.9070 and 0.9077, and for liver 0.8881, 0.8880 and 0.8890, so their ranking ability is practically the same even though Random Forest "
          "has lower accuracy and recall at the 0.5 cut-off. The Decision Tree has the lowest AUC for every disease (0.7339 to 0.8072)."),
        H2("8.4 Stability of the Model Choice"),
        P("A 400-row test set with a single split gives noisy numbers, and the training script chooses the best model on that same test set. To see whether the choice survives, all four algorithms were re-evaluated by stratified 5-fold cross-validation "
          "and on ten further random 80/20 splits."),
    ]
    rows = []
    for d in D:
        for m in F.MODEL_ORDER:
            c, s = X[d]["cv5"][m], X[d]["seed_study"][m]
            rows.append([NAME[d] if m == F.MODEL_ORDER[0] else "", F.SHORT[m], ms(c, "accuracy"), ms(c, "f1"), ms(c, "auc"), ms(s, "accuracy"), str(X[d]["seed_winners"][m])])
    out += [
        TAB("5-fold cross-validation and ten random splits (mean ± standard deviation)", ["Disease", "Model", "CV accuracy", "CV F1", "CV ROC-AUC", "Split accuracy", "Best-F1 splits of 10"],
            rows, widths=[0.9, 0.5, 1.15, 1.15, 1.15, 1.15, 0.7], align=["l", "c", "c", "c", "c", "c", "c"], size=8),
        FIG(F.fig("stability.png"), "Accuracy on the seed-42 hold-out split, in 5-fold cross-validation and on ten random splits (error bars: one standard deviation; dashed line: 92% noise ceiling)", FIG_W),
        P("**Logistic Regression has the best F1 on 10 of 10 splits for all four diseases**, and the best or tied-best cross-validated accuracy. The diabetes row is the notable case: on the seed-42 split the SVM has the higher F1 (0.8636 against 0.8599), "
          "and `train_models.py` therefore saved the SVM; on cross-validation and on every one of the ten other splits Logistic Regression is better (CV accuracy 0.8955 against 0.8765; split accuracy 0.8925 against 0.8675). "
          "The difference on the chosen split is far inside the split-to-split standard deviation of about 0.013 to 0.015, so the selection picked a model that the other evidence does not support. "
          f"Selecting on the same data that is then used to report the score also makes the reported figures slightly optimistic, a known source of bias in model selection {cite('varma')}. "
          "A nested or separate validation split, as the base paper uses, would avoid it."),
        H2("8.5 Over-fitting and Hyper-parameter Sensitivity"),
        FIG(F.fig("train_test_gap.png"), "Training and test accuracy of the four algorithms for each disease", FIG_W),
        P("Random Forest fits the training rows to 93.6-95.9% but reaches only 81.5-88.3% on the test rows; its 200 trees of depth 8 fit the flipped labels. "
          "Logistic Regression's training and test accuracy are within about three points (heart 91.1% against 88.5%, the largest gap), which is what a model with few parameters on 1,600 rows should show."),
        FIG(F.fig("sensitivity.png"), "Test accuracy against decision-tree depth, forest size and SVM C, for the four diseases", FIG_W),
        P("The settings in `train_models.py` were never tuned and no grid search was run, so a sensitivity sweep shows how much was left on the table. Decision trees peak at depth 4 to 8 and decline beyond (diabetes 0.8200 at depth 4, 0.7675 at depth 12), "
          "random forests are flat beyond 50 trees, and the RBF SVM is best at C between 0.3 and 1 and falls to 0.7700-0.8300 at C = 100. The shipped settings (depth 6, 200 trees, C = 1) sit near the best values, so tuning would change the scores by a point or two, not more."),
        H2("8.6 Decision-threshold Analysis"),
        P("The application uses each model's own decision rule, which corresponds to a probability threshold of 0.5. The sweep below uses the predicted probability of the high-risk class of the served model on the test split "
          "(for the SVM this is the probability from Platt scaling, so its 0.50 row differs slightly from the `predict` result in Section 8.2)."),
    ]
    rows = []
    for d in D:
        s5, bs = sweep(d, 0.5), best_sweep(d)
        r90 = [s for s in X[d]["threshold_sweep"] if s["recall"] >= 0.90]
        r90 = max(r90, key=lambda s: s["threshold"]) if r90 else None
        rows.append([NAME[d], f"{s5['precision']:.3f} / {s5['recall']:.3f} / {s5['f1']:.3f}", f"{bs['threshold']:.2f}: {bs['f1']:.3f}",
                     (f"{r90['threshold']:.2f}: P {r90['precision']:.3f}" if r90 else "not reached (0.20-0.80)")])
    out += [
        TAB("Effect of the decision threshold (served model, test split)", ["Disease", "At 0.50: precision / recall / F1", "Best F1 threshold: F1", "Highest threshold with recall ≥ 0.90"],
            rows, widths=[1.2, 1.9, 1.4, 1.5], align=["l", "c", "c", "c"], size=9),
        FIG(F.fig("threshold_sweep.png"), "Precision, recall and F1 against the decision threshold for the four served models (dashed line: 0.5)", FIG_W),
        P("F1 is nearly flat around 0.5 for every disease; the best threshold is 0.55 for heart and 0.50 for the other three, so the default is reasonable. For a screening use, where missing a patient costs more than a false alarm, the threshold could be lowered: "
          "for diabetes recall reaches 0.907 at a threshold of 0.20, at the price of precision 0.656. For liver disease recall never reaches 0.90 in the range 0.20-0.80. "
          "The application does not let the user change the threshold; this is listed as future work."),
        H2("8.7 Which Inputs Matter"),
        FIG(F.fig("importance.png"), "Permutation importance of the six strongest inputs for each served model (drop in test accuracy when the input is shuffled)", FIG_W),
    ]
    imp = "; ".join(f"{NAME[d].lower()}: " + ", ".join(f"{p['feature']} ({p['mean']:.3f})" for p in X[d]["perm_importance"][:3]) for d in D)
    out += [
        P(f"The three strongest inputs by permutation importance are, for each disease, {imp}. They are the inputs that carry the largest weight in the risk rule inside `generate_data.py`, which is expected because the labels were built from that rule; "
          "the analysis confirms that the models recover it. It was run offline for this report. **The application itself does not show which inputs drove a prediction**, so the sixth objective is only partly met (Section 8.13)."),
        H2("8.8 Supplementary Check on Real Public Data"),
        P(f"Because the main results rest on synthetic data, the same four algorithms with the same settings were also trained and cross-validated on public data sets with the matching columns: the Pima Indians Diabetes data {cite('pima')}, "
          f"the Cleveland heart-disease data {cite('cleveland')}, the Indian Liver Patient data (ILPD) {cite('ilpd')} and the chronic kidney disease data {cite('ckd')}. Missing values (Pima zeros treated as missing, and the blank cells counted in the table below) "
          "were filled with the median inside each fold; the check is a supplementary script and is not part of the application."),
    ]
    rows = [[NAME[d], R[d]["source"], str(R[d]["rows"]), f"{R[d]['positive']} / {R[d]['negative']}", str(R[d]["missing_cells"]), F.pct(R[d]["majority_rate"])] for d in D]
    out.append(TAB("Real data sets used in the supplementary check", ["Disease", "Source", "Rows", "Positive / negative", "Missing cells", "Majority-class rate"], rows,
                   widths=[1.0, 2.2, 0.5, 0.9, 0.7, 0.7], align=["l", "l", "c", "c", "c", "c"], size=8.5))
    rows = []
    for d in D:
        for m in F.MODEL_ORDER:
            c = R[d]["real_cv"][m]
            rows.append([NAME[d] if m == F.MODEL_ORDER[0] else "", F.SHORT[m], f"{c['accuracy_mean']:.3f} ± {c['accuracy_std']:.3f}", f"{c['f1_mean']:.3f}", f"{c['auc_mean']:.3f}"])
    out.append(TAB("(a) Algorithms trained and cross-validated on the real data (5-fold, repeated 3 times)", ["Disease", "Model", "Accuracy", "F1", "ROC-AUC"], rows,
                   widths=[1.3, 0.7, 1.5, 0.9, 0.9], align=["l", "c", "c", "c", "c"], size=9))
    rows = []
    for d in D:
        s = R[d]["shipped_on_real"]
        rows.append([NAME[d], s["model"], f"{s['accuracy']:.3f}", f"{s['recall']:.3f}", f"{s['roc_auc']:.3f}", F.pct(s["predicted_positive_rate"]), F.pct(R[d]["majority_rate"])])
    out += [
        TAB("(b) The shipped (synthetic-trained) models applied to every real record", ["Disease", "Shipped model", "Accuracy", "Recall", "ROC-AUC", "Predicted positive", "Majority baseline"], rows,
            widths=[1.0, 1.4, 0.7, 0.65, 0.7, 0.8, 0.75], align=["l", "l", "c", "c", "c", "c", "c"], size=9),
        FIG(F.fig("real_vs_synthetic.png"), "Accuracy on synthetic data (CV), on real data (CV) and of the shipped models on real records, with the majority-class baseline", FIG_W),
        P("**Findings.** (1) On real data the best algorithm reaches 76.5% for diabetes, 84.3% for heart disease, 71.8% for liver disease and 98.8% for kidney disease, against 87.8-90.4% in cross-validation on the synthetic data; "
          "the kidney set is almost separable, the others are much noisier than the synthetic data. (2) The shipped models transfer only partly: their ROC-AUC on real records is 0.796, 0.884, 0.745 and 0.992, so the ranking of risk carries over, "
          "but the 0.5 decision rule does not fit real populations. For liver disease the shipped model's accuracy of 54.0% is **below the 71.4% majority-class baseline** (it flags only 28.8% of patients, while 71.4% of the records are positive). "
          "(3) The heart codes (chest-pain type, slope, thalassemia) had to be recoded to the project's coding, and the thalassemia mapping is arbitrary. "
          "The more honest estimate of how this method behaves on patients is therefore the real-data table, and the application must not be used for clinical decisions."),
        H2("8.9 Testing and Performance"),
    ]
    groups = {}
    for c in A["checks"]:
        if c["group"] != "observation":
            g = groups.setdefault(c["group"], [0, 0])
            g[1] += 1
            g[0] += int(c["passed"])
    desc = {"functional": "Every endpoint, both classes, all four diseases; metadata matches the form fields",
            "consistency": "API prediction equals a direct `model.predict` on 40 sampled rows; the same input twice gives the same output",
            "validation": "Missing, empty, text, NaN, infinite and null values give 422; unknown disease 404; malformed JSON 422; wrong method 405",
            "sanity": "An extreme low-risk and an extreme high-risk diabetes record are classified correctly"}
    rows = [[g.capitalize(), f"{v[0]} / {v[1]}", desc.get(g, "")] for g, v in groups.items()]
    rows.append(["Smoke test", f"{F.SMOKE_CHECKS} / {F.SMOKE_CHECKS}", "`scripts/smoke_test.py`: health, lists, report, datasets, samples and predictions for each disease, invalid input and unknown disease"])
    lat = A["latency"]
    lrows = [[k, f"{v['p50_ms']:.1f}", f"{v['p95_ms']:.1f}", f"{v['max_ms']:.1f}"] for k, v in lat.items()]
    thr = lat["POST /api/predict/diabetes (4 concurrent clients)"]["throughput_rps"]
    t = X["diabetes"]["timing"]
    out += [
        TAB(f"API checks ({F.API_CHECKS[0]} of {F.API_CHECKS[1]} passed in `scripts/api_tests.py`)", ["Group", "Passed", "What is checked"], rows, widths=[1.1, 0.8, 4.1], align=["l", "c", "l"], size=9),
        P("Two observations are recorded but are not failures: the API accepts physiologically impossible values (a glucose of 100,000 mg/dL returns High Risk with 60.94%, an age of -5 returns High Risk with 74.61%), because the only range check is a warning in the web form. "
          "There is no pytest suite, no frontend test, no security test (the application has no sign-in) and no load test beyond the one below."),
        TAB("Measured API latency on 127.0.0.1 (200 calls after 10 warm-up calls)", ["Request", "Median (ms)", "95th percentile (ms)", "Max (ms)"], lrows, widths=[3.3, 0.9, 1.0, 0.8], align=["l", "c", "c", "c"], size=9),
        FIG(F.fig("api_latency.png"), "Median and 95th-percentile latency of the API routes", 4.8),
        P(f"A prediction takes about 14 ms at the median and about 25 ms at the 95th percentile; with four concurrent clients the service handled {thr:.0f} requests per second. "
          "Windows timer resolution (about 15.6 ms) quantises single-call timings and the machine was under memory pressure from other programs while these were taken, so the values are upper bounds and a prediction takes well under 25 ms in practice. "
          f"In process, fitting the four diabetes models takes {t['Logistic Regression']['fit_s'] * 1000:.0f} ms (Logistic Regression), {t['Decision Tree']['fit_s'] * 1000:.0f} ms (Decision Tree), {t['Random Forest']['fit_s'] * 1000:.0f} ms (Random Forest) and {t['SVM']['fit_s'] * 1000:.0f} ms (SVM), "
          f"and predicting one row takes {t['Logistic Regression']['predict_ms_per_row']:.4f} to {t['SVM']['predict_ms_per_row']:.4f} ms."),
        H2("8.10 Comparison with the Base Paper"),
        P(f"The base paper {cite('base')} diagnoses thyroid disease on a real data set, so **its results are not comparable with this project's**; the comparison is for context and is not a like-for-like comparison. The two differ in disease, data, class structure and evaluation protocol."),
        TAB("Base paper compared with this project", ["Aspect", "Base paper (Alam et al., 2026)", "This project"],
            [["Disease(s)", "Thyroid status (Normal, Hypothyroid, Hyperthyroid), three classes", "Diabetes, heart, liver and kidney disease, each a binary high-risk / low-risk task"],
             ["Data", "UCI thyroid data, 7,200 samples, 21 features, strongly imbalanced, real", "Four synthetic CSVs of 2,000 rows each (8,000 rows); real data only in a supplementary check"],
             ["Classifiers", "SVC, Random Forest, Extra Trees, AdaBoost, CatBoost", "Logistic Regression, Decision Tree, Random Forest, SVM"],
             ["Evaluation", "Nested cross-validation (5 outer folds, 3-fold inner grid search); full set and top-10 features", "One 80/20 hold-out split with fixed settings, plus cross-validation and ten splits as extra checks"],
             ["Imbalance", "SMOTE tried and rejected (minority recall improved by under 2%)", "Not applied; not needed on the synthetic class balance"],
             ["Reported performance", "Random Forest accuracy and F1 0.996-0.997, ROC-AUC 0.999-1.000; SVC accuracy 0.965-0.967, ROC-AUC 0.990-0.992", f"Served models: accuracy {F.pct(min(F.HO[d][F.BEST[d]]['accuracy'] for d in D))}-{F.pct(max(F.HO[d][F.BEST[d]]['accuracy'] for d in D))}, ROC-AUC 0.8455-0.9077 on synthetic data; 71.8-98.8% accuracy on real data"],
             ["Explainability", "SHAP and counterfactual explanations", "None in the application (offline permutation importance only)"],
             ["Scope", "One disease, a modelling study", "Four diseases behind one web interface, with a prediction API"]],
            widths=[1.1, 2.5, 2.4], size=8.5),
        P("The project reuses the base paper's idea of comparing several classical classifiers by held-out evaluation and extends the scope from one disease to four behind a single interface. It does not reproduce the thyroid experiment, "
          "and its lower figures on real data (71.8-98.8% accuracy) should not be read against the paper's 0.99+, which is for a different, much more separable task and uses nested cross-validation and tuning that this project does not."),
        H2("8.11 Success and Failure Cases"),
        B("**Success.** The application predicts for all four diseases in a few milliseconds, the API handled every malformed request with a clear 422 or 404, and for a low-risk and a high-risk sample record of each disease the models agree with the label in most cases (screens in Section 8.12).",
          "**Success.** For every disease the served model is within about four points of the 92% accuracy that the label noise allows, so the pipeline recovers the rule the data were built from.",
          f"**Failure: missed patients.** The diabetes model misses {cm('diabetes')[2]} of {cm('diabetes')[2] + cm('diabetes')[3]} high-risk test rows and the liver model {cm('liver')[2]} of {cm('liver')[2] + cm('liver')[3]}; for a screening tool these false negatives are the costly error.",
          f"**Failure: false alarms.** The heart model flags {cm('heart')[1]} of {cm('heart')[0] + cm('heart')[1]} low-risk rows. Screen 20 shows one: a record labelled low-risk is classified Positive (High Risk) with a displayed confidence of 99.53%.",
          "**Failure: confidence is not correctness.** The percentage shown is the model's probability for the class it predicted (50-100%), not the chance that the prediction is right; the false positive above has the highest confidence of any screen.",
          "**Failure: transfer to real records.** The shipped liver model scores 54.0% on real ILPD records, below the 71.4% majority baseline; the diabetes (75.0% against 65.1%), heart (69.6% against 54.1%) and kidney (82.3% against 62.5%) models stay above the baseline but far below their synthetic-data scores.",
          "**Failure: no range validation.** Impossible values such as glucose 100,000 are accepted by the API and classified.",
          "**Failure: model choice.** The diabetes model is an SVM although Logistic Regression is better on cross-validation and on ten of ten splits."),
        H2("8.12 Output Screens"),
        P("The screens were captured from the running application at 1440 x 900 (Chrome driven by Playwright, scripts `capture_screens.py` and `capture_extra.py`). The prediction screens use real rows drawn from the training CSV by the \"Positive sample\" and \"Negative sample\" buttons; "
          "the Datasets screen carries the application's own warning that the data are synthetic. Screens that do not show a prediction (landing, about, not-found) are in Appendix C."),
        FIGPAIR((shot("04_overview.png"), "Overview page: four conditions, 43 clinical inputs, 16 models trained, best accuracy 91.8% (liver, Logistic Regression) and the test accuracy of the selected model for each condition"), (shot("05_predict-diabetes.png"), "Diabetes prediction for a positive sample: Positive (High Risk), confidence 90.71%, SVM, test accuracy 89.5%")),
        FIGPAIR((shot("06_predict-heart.png"), "Heart disease prediction for a positive sample (Logistic Regression)"), (shot("07_predict-liver.png"), "Liver disease prediction for a positive sample (Logistic Regression)")),
        FIGPAIR((shot("08_predict-kidney.png"), "Kidney disease prediction for a positive sample (Logistic Regression)"), (shot("13_predict-diabetes-low-risk.png"), "Diabetes prediction for a negative sample classified Negative (Low Risk)")),
        FIGPAIR((shot("14_predict-heart-low-risk.png"), "Heart disease prediction for a negative sample classified Low Risk"), (shot("15_predict-liver-low-risk.png"), "Liver disease prediction for a negative sample classified Negative (Low Risk)")),
        FIGPAIR((shot("16_predict-kidney-low-risk.png"), "Kidney disease prediction for a negative sample classified Low Risk"), (shot("20_predict-heart-false-positive.png"), "Failure case: a heart record labelled low-risk in the data that the model classifies Positive (High Risk) with 99.53% confidence")),
        FIGPAIR((shot("09_models.png"), "Models page: metric bars and sortable score table for the four algorithms (diabetes tab)"), (shot("10_datasets.png"), "Datasets page: row counts and class balance of the four CSV files, with the warning that they are synthetic")),
        FIGPAIR((shot("17_validation-error.png"), "Validation: pressing Predict on an empty diabetes form marks all eight fields as required and does not call the API"), (shot("18_out-of-range-warning.png"), "Out-of-range warning: a glucose of 900 mg/dL is outside the training range (60-229.7) and the form warns that the estimate may be less reliable")),
        FIG(shot("19_predict-heart-mobile.png"), "Phone layout (390 x 844 px): the heart form with a sample loaded and the sidebar collapsed into a menu", 2.2),
        H2("8.13 Objectives versus Outcomes"),
    ]
    from .shared import OBJECTIVES, OBJECTIVE_STATUS

    out += [
        TAB("Objectives of the project against what was measured", ["#", "Objective", "Status", "Evidence"],
            [[str(i), o, s, e] for i, (o, (s, e)) in enumerate(zip(OBJECTIVES, OBJECTIVE_STATUS), 1)], widths=[0.3, 1.9, 0.8, 3.0], align=["c", "l", "c", "l"], size=8.5),
        P("Two further promises in the abstract are not met: the system does not produce \"healthcare recommendations\" and it does not perform feature selection. The result card shows only the class, the confidence and a not-a-diagnosis notice."),
        H2("8.14 Discussion and Threats to Validity"),
        B("**What the results support.** The pipeline works end to end for four diseases; four classical algorithms can be compared fairly on one split; a linear model recovers a linear rule best; and an interface and API around the models respond in milliseconds.",
          "**What they do not support.** Any claim about accuracy on patients; a claim that Random Forest or SVM is better than Logistic Regression here; calibrated probabilities; or clinical usefulness.",
          "**Data validity.** The data are synthetic and the label is built from the same features the model sees, so the relationships are cleaner and more linear than in real data; the real-data check shows the gap.",
          "**Statistical validity.** Each test set has 400 rows (112 to 292 high-risk), so single-split differences of one to two points are noise; cross-validation and ten splits were added for that reason.",
          "**Selection bias.** The served model is chosen on the same test set that reports its score.",
          "**Explanation validity.** Importance was computed offline on the same data and mirrors the generator; it says nothing about clinical causes.",
          f"**Comparability.** The base paper {cite('base')} and this project use different diseases, data and protocols; the metrics are not comparable."),
    ]
    return out
